from pathlib import Path
p=Path('dashboard.html');s=p.read_text(encoding='utf-8');M='WINTURBO_SIGNUP_REQUEST_FIX_V41'
if M in s: raise SystemExit('v41 present')
js=r'''<script>/* WINTURBO_SIGNUP_REQUEST_FIX_V41 */
(function(){async function submit(){const b=document.getElementById('submitSignupV39'),msg=document.getElementById('signupMsgV39');if(!b||!msg)return;b.disabled=true;const email=document.getElementById('signupEmailV39')?.value.trim(),full_name=document.getElementById('signupNameV39')?.value.trim();if(!email){msg.textContent='Please enter your email.';b.disabled=false;return}msg.textContent='Sending account request…';try{const r=await sb.functions.invoke('request-dashboard-access',{body:{email,full_name}});if(r.error)throw r.error;msg.textContent=r.data?.status==='approved'?'This email is already approved. Please use Sign In.':'Account request submitted. An administrator will review it under Verification. No activation email is sent at this stage.';document.getElementById('signupPasswordV39')?.setAttribute('disabled','disabled')}catch(e){msg.textContent=e?.message||'Could not submit account request.'}finally{b.disabled=false}}
function bind(){const old=document.getElementById('submitSignupV39');if(!old)return;const n=old.cloneNode(true);old.parentNode.replaceChild(n,old);n.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();submit()});const pw=document.getElementById('signupPasswordV39');if(pw){pw.style.display='none';pw.disabled=true}const form=document.getElementById('signupFormV39');if(form&&!form.querySelector('.v41note')){const x=document.createElement('div');x.className='muted small v41note';x.textContent='No password or confirmation email is required until an administrator approves your request.';form.insertBefore(x,n)}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(bind,1200),{once:true});else setTimeout(bind,1200)})();</script>'''
s=s.replace('</body>',js+'\n</body>',1);p.write_text(s,encoding='utf-8')